"'$s = Get-Content -LiteralPath datos/PN09822PM.json -Raw -Encoding utf8 | ConvertFrom-Json
$months = '"'Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'
"'$expected = @(foreach ($year in 2020..2024) { foreach ($month in $months) { "$month.$year" } })
$actual = @($s.periods | ForEach-Object { $_.name })
if ($actual.Count -ne $expected.Count -or ($actual | Sort-Object -Unique).Count -ne $expected.Count -or (Compare-Object $actual $expected)) { throw '"'Cobertura mensual inesperada' }
"'$culture = [Globalization.CultureInfo]::InvariantCulture
$rates = @($s.periods | ForEach-Object {
  $rate = 0d
  if ($_.values.Count -ne 1 -or -not [decimal]::TryParse([string]$_.values[0], [Globalization.NumberStyles]::Float, $culture, [ref]$rate)) { throw '"'Valor faltante o no numérico' }
  [pscustomobject]@{Year=[int]("'$_.name.Split('"'.')[1]); Rate="'$rate}
})
$above = @($rates | Where-Object { $_.Rate -gt 8 })
[pscustomobject]@{
 Total = $rates.Count
 Mayor8 = $above.Count
 Igual8 = @($rates | Where-Object { $_.Rate -eq 8 }).Count
 Menor8 = @($rates | Where-Object { $_.Rate -lt 8 }).Count
 PorAnio = @(foreach ($year in 2020..2024) { [pscustomobject]@{ Anio=$year; Meses=@($above | Where-Object { $_.Year -eq $year }).Count } })
} | ConvertTo-Json -Depth 4'

